description:
Design a 32-bit Arithmetic Logic Unit (ALU) that performs various arithmetic and logic operations based on a 4-bit control signal. The ALU supports operations including bitwise AND, OR, addition, subtraction, comparison (less than), and bitwise NOR. It outputs the result of the selected operation as ALU_result and provides a zero output that indicates whether the result is zero. The ALU responds to the control signals to execute the corresponding operation by using a combinational logic block.
module top_module(
		ALU_Control, 
		operand_A, operand_B, 
		ALU_result, zero
);

code:
module top_module(
		ALU_Control, 
		operand_A, operand_B, 
		ALU_result, zero
);input [3:0]   ALU_Control; 
input [31:0]  operand_A ;
input [31:0]  operand_B ;
output reg zero; 
output reg [31:0] ALU_result;




always@(*)
begin
	case(ALU_Control)
		4'b0000: ALU_result = operand_A & operand_B;
		4'b0001: ALU_result = operand_A | operand_B;
		4'b0010: ALU_result = operand_A + operand_B;	
		4'b0110: ALU_result = operand_A - operand_B;
		4'b0111: ALU_result = (operand_A < operand_B) ? 1 : 0;
		4'b1100: ALU_result = ~(operand_A | operand_B);

		default: ALU_result = "HIHIHI";
	endcase 


	if(ALU_result == 32'b0)
	begin
		zero = 1;
	end
	else
	begin
		zero = 0;
	end
end



endmodule

